insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'How Remote Online Notarization Works','how-remote-online-notarization-works','A practical walk-through of a Texas remote online notarization, from device check to the completed electronic record.','[["h2","A live notarial act, completed online"],["p","Remote online notarization (RON) lets a signer and a Texas-commissioned online notary meet by live audio-video technology. It is not an automated stamp or a document-review service. The notary still identifies the signer, observes the signing or acknowledgment, completes the notarial certificate, and creates the records required for the online act."],["h2","The five-part appointment flow"],["ol",["Submit a service request and tell APS what type of document and notarial act the receiving party expects.","Open the secure session on a supported phone, tablet, or computer with a camera, microphone, reliable internet, and a private place to talk.","Complete the platform''s identity steps. These may include credential analysis of a government-issued ID and dynamic knowledge-based authentication (KBA).","Meet the notary by live audio-video. The notary confirms willingness and awareness, administers an oath when the act requires one, and watches the required action.","The notary applies the electronic certificate and seal in the approved platform. Delivery timing depends on the document and service workflow."]],["callout","The notary verifies identity and performs the notarial act. The notary does not decide whether a document is legally sufficient, choose the certificate for you, or give legal advice."],["h2","Location and eligibility"],["p","A Texas online notary must be physically located in Texas when performing the notarization. A signer may be elsewhere, but the document, receiving party, platform, and applicable law must allow the transaction. Some documents or circumstances may require an in-person appointment."],["h2","Before you begin"],["ul",["Confirm the receiving party accepts remote online notarization.","Use your own email address and a device you control.","Have an acceptable, unexpired government-issued photo ID available.","Do not pre-sign a document when the requested act requires signing in the notary''s presence.","Keep sensitive document contents out of ordinary email or feedback forms."]]]'::jsonb,'[["Can I use my phone?","Often, yes, when the platform supports the device and the camera, microphone, browser, and connection work reliably."],["What if I cannot pass identity verification?","APS cannot bypass or answer identity questions. A neutral next step may be to retry only when the platform permits, confirm your information, or request an in-person option."],["Does APS choose the notarial certificate?","No. The signer or receiving party must identify the requested notarial act; a notary cannot provide legal advice."]]'::jsonb,'[{"label":"Texas Secretary of State — Online Notary Public Educational Information","url":"https://www.sos.state.tx.us/statdoc/online-np-educational.shtml"},{"label":"Texas Secretary of State — Identity Proofing and Credential Analysis","url":"https://www.sos.state.tx.us/statdoc/identityproofing.shtml"}]'::jsonb,'How Remote Online Notarization Works | Aligned Print & Scan','A practical walk-through of a Texas remote online notarization, from device check to the completed electronic record.','published',true,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/ron-home-session.webp' where c.name='Online Notary' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'What You Need for an Online Notary Appointment','what-you-need-online-notary-appointment','Use this privacy-conscious checklist to prepare your device, identification, document, and environment before a remote session.','[["h2","Your appointment checklist"],["ul",["A supported smartphone, tablet, or computer with a working camera and microphone.","A stable internet connection and enough battery power for the full session.","A quiet, well-lit place where you can speak and appear on camera.","An acceptable, unexpired government-issued photo ID.","The complete document, with the notarial certificate or receiving-party instructions available.","Access to your email and phone if the platform sends a secure link or verification code."]],["h2","Protect your information"],["p","Use only the secure session and upload methods APS provides. Do not place Social Security numbers, ID images, bank information, passwords, or document contents in a Resource Center question, feedback form, or ordinary email."],["h2","Do not pre-sign automatically"],["p","An acknowledgment and a jurat have different signing and oath requirements. If you are unsure whether to sign before the appointment, ask the document''s receiving party or wait for the notary''s procedural direction during the session."],["callout","Identity checks are performed by the approved technology provider. APS cannot supply KBA answers, alter results, or promise that every signer or document will qualify for RON."]]'::jsonb,'[["Do I need an app?","Platform requirements vary. Follow only the secure appointment instructions APS sends."],["Can another person help me?","Someone may help with technology when appropriate, but the notary must communicate with and assess the signer directly."],["What if my document is incomplete?","Contact the document preparer or receiving party. A notary cannot fill legal blanks or advise what the document should say."]]'::jsonb,'[{"label":"Texas Secretary of State — Online Notary Public Educational Information","url":"https://www.sos.state.tx.us/statdoc/online-np-educational.shtml"},{"label":"Texas Secretary of State — Identity Proofing and Credential Analysis","url":"https://www.sos.state.tx.us/statdoc/identityproofing.shtml"}]'::jsonb,'What You Need for an Online Notary Appointment | Aligned Print & Scan','Use this privacy-conscious checklist to prepare your device, identification, document, and environment before a remote session.','published',false,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/secure-digital-workspace.webp' where c.name='Online Notary' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'Can I Notarize a Document From My Phone?','notarize-from-phone','What a phone-based remote notarization requires, common setup problems, and when a larger device may be the better choice.','[["h2","A phone can work when the platform supports it"],["p","Many remote notarization sessions can be completed on a modern smartphone. The decisive factors are platform compatibility, a reliable browser or app, a clear camera, working audio, and a stable connection—not simply the age of the phone."],["h2","Set up for a smoother session"],["ul",["Charge the phone and connect to dependable Wi-Fi or strong cellular service.","Allow camera and microphone access only for the secure platform.","Use a stand or stable surface so the image does not shake.","Choose bright, front-facing light and avoid a window behind you.","Keep your email available without closing the session.","Use a larger device if the document is long or text is difficult to review."]],["h2","Know when to switch devices"],["p","A computer or tablet may be easier when the document has many pages, the platform requires side-by-side review, accessibility settings are needed, or the phone repeatedly drops the session. Switching devices does not change the identity or notarial requirements."],["callout","Never send an ID photo or sensitive document through a Resource Center form. Use the secure appointment channel provided for the transaction."]]'::jsonb,'[["Can I use a borrowed phone?","A device you control is preferable. You must be able to access the secure link and complete the identity steps privately."],["Can I join from a moving car?","No. Use a safe, stationary, private location with consistent audio and video."],["Will every phone work?","No. Compatibility depends on the platform, operating system, browser, permissions, and connection."]]'::jsonb,'[{"label":"Texas Secretary of State — Online Notary Public Educational Information","url":"https://www.sos.state.tx.us/statdoc/online-np-educational.shtml"},{"label":"Texas Secretary of State — Identity Proofing and Credential Analysis","url":"https://www.sos.state.tx.us/statdoc/identityproofing.shtml"}]'::jsonb,'Can I Notarize a Document From My Phone? | Aligned Print & Scan','What a phone-based remote notarization requires, common setup problems, and when a larger device may be the better choice.','published',false,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/identity-verification-devices.webp' where c.name='Online Notary' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'Understanding Identity Verification and KBA for Online Notarization','identity-verification-kba-online-notarization','A neutral explanation of credential analysis, dynamic knowledge-based authentication, privacy, and what happens after an unsuccessful check.','[["h2","Two different identity controls"],["p","Texas online notarization commonly uses credential analysis and identity proofing. Credential analysis evaluates a government-issued identification credential using approved technology. Identity proofing may use dynamic knowledge-based authentication (KBA), which generates questions from public and proprietary data sources."],["h2","The notary does not create or see your answers"],["p","The third-party provider delivers the questions and evaluates the result. The notary does not choose the questions, supply answers, or override the provider. APS should never ask you to disclose KBA answers."],["h2","If a check is unsuccessful"],["p","An unsuccessful result is not a character judgment and APS does not speculate about the reason. Follow the platform''s neutral instructions. A permitted retry, correction of an input error, or an in-person notary appointment may be available, but no outcome is guaranteed."],["callout","Use only the secure identity flow. Never place an ID number, KBA answer, Social Security number, banking detail, or password in an APS feedback or article-question form."]]'::jsonb,'[["Can APS tell me why I failed KBA?","APS generally receives a result, not the underlying personal-data rationale, and cannot override it."],["Can someone help answer the questions?","No. The signer must complete identity proofing independently."],["Is a photo ID still needed?","Credential analysis generally requires an acceptable government-issued identification credential."]]'::jsonb,'[{"label":"Texas Secretary of State — Online Notary Public Educational Information","url":"https://www.sos.state.tx.us/statdoc/online-np-educational.shtml"},{"label":"Texas Secretary of State — Identity Proofing and Credential Analysis","url":"https://www.sos.state.tx.us/statdoc/identityproofing.shtml"}]'::jsonb,'Understanding Identity Verification and KBA for Online Notarization | Aligned Print & Scan','A neutral explanation of credential analysis, dynamic knowledge-based authentication, privacy, and what happens after an unsuccessful check.','published',false,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/identity-verification-devices.webp' where c.name='Online Notary' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'Mobile Notary vs. Remote Online Notary','mobile-notary-vs-remote-online-notary','Compare travel, technology, identity steps, document handling, and practical fit before requesting a notary service.','[["h2","The central difference"],["p","A mobile notary travels to an agreed physical location. A remote online notary and signer meet by live audio-video through an approved technology platform while the Texas online notary is physically in Texas."],["h2","When mobile may fit"],["ul",["The document or receiving party requires a physical appearance or wet-ink original.","A signer cannot complete online identity proofing.","Technology, internet access, accessibility, or document format makes an online session impractical.","Several physical documents or signers need coordinated handling."]],["h2","When RON may fit"],["ul",["The receiving party accepts remote online notarization.","The signer has compatible technology and acceptable identification.","Travel or scheduling makes a live online appointment more convenient.","The document can be completed and delivered electronically through the approved workflow."]],["callout","APS can explain service logistics and fees. APS cannot determine which form of notarization a legal transaction requires; confirm that with the receiving party or qualified legal counsel."]]'::jsonb,'[["Is one option more valid?","Validity depends on the governing law, required act, document, execution, and receiving party—not convenience alone."],["Does a mobile notary charge travel?","Mobile service pricing may include travel based on the service location and quoted route."],["Can APS switch my request?","Ask as early as possible. Eligibility, availability, pricing, and document requirements must be reviewed."]]'::jsonb,'[]'::jsonb,'Mobile Notary vs. Remote Online Notary | Aligned Print & Scan','Compare travel, technology, identity steps, document handling, and practical fit before requesting a notary service.','published',false,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/mobile-notary-family.webp' where c.name='Notary Basics' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'Acknowledgment vs. Jurat','acknowledgment-vs-jurat','Understand the practical distinction between two common notarial acts without asking the notary to choose for you.','[["h2","An acknowledgment focuses on acknowledgment"],["p","For an acknowledgment, the signer appears before the notary and acknowledges signing the document for its stated purpose. Depending on the circumstances and applicable requirements, the signature may already be on the document."],["h2","A jurat includes an oath or affirmation"],["p","For a jurat, the signer signs in the notary''s presence and swears or affirms that the statements in the document are true. The notary administers the oath or affirmation."],["h2","Who chooses the act?"],["p","The signer, document preparer, receiving party, or qualified legal adviser must identify the required act. A notary may describe procedural differences but cannot select a certificate as legal advice."],["callout","Bring the document and any receiving-party instructions. Do not ask APS to decide which certificate your legal document needs."]]'::jsonb,'[["Can a notary explain the difference?","Yes, a notary may describe the procedures, but cannot decide which act you need."],["Can I pre-sign a jurat?","A jurat requires signing in the notary''s presence."],["Does the document title decide the act?","Not necessarily. Obtain clear direction from the receiving party or document preparer."]]'::jsonb,'[]'::jsonb,'Acknowledgment vs. Jurat | Aligned Print & Scan','Understand the practical distinction between two common notarial acts without asking the notary to choose for you.','published',false,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/aligned-notary-seal-detail.webp' where c.name='Notary Basics' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'How to Prepare a Document for Notarization','prepare-document-for-notarization','A practical, privacy-aware checklist for document completeness, certificate instructions, identification, signers, and witnesses.','[["h2","Review before the appointment"],["ul",["Confirm the document is complete and belongs to the intended transaction.","Ask the receiving party which notarial act is required when the certificate is unclear or absent.","Do not fill in a notarial certificate reserved for the notary.","Check whether witnesses are required and who may serve.","Bring acceptable identification and ensure names are reasonably consistent.","Do not pre-sign when the act requires signing before the notary."]],["h2","Keep legal decisions with the right person"],["p","APS can describe its process, schedule a service, and identify incomplete logistics. APS does not draft legal documents, advise what language to use, decide whether a transaction is in your interest, or select a notarial act."],["h2","Protect document contents"],["p","Use approved secure upload and delivery channels. Resource Center forms are for general questions only and must not contain SSNs, ID details, banking data, passwords, or document contents."],["callout","If a document has blanks, conflicting instructions, or a missing certificate, contact the preparer or receiving party before the appointment."]]'::jsonb,'[["Can APS fill blank spaces?","APS cannot complete legal content for you."],["What if my ID name differs?","Tell APS during scheduling without sending ID details in an ordinary message; the notary must evaluate identification at the appointment."],["Can APS provide witnesses?","Ask during scheduling. Availability, eligibility, and fees must be confirmed."]]'::jsonb,'[]'::jsonb,'How to Prepare a Document for Notarization | Aligned Print & Scan','A practical, privacy-aware checklist for document completeness, certificate instructions, identification, signers, and witnesses.','published',false,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/secure-document-handling.webp' where c.name='Notary Basics' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'What to Expect at a Loan Signing Appointment','what-to-expect-loan-signing-appointment','Prepare for the timing, identification, document handling, and neutral role of a notary signing agent at a loan signing.','[["h2","Before the appointment"],["p","The ordering organization sets the package, signing instructions, appointment terms, and return requirements. Confirm the time and location, have acceptable identification ready, and direct loan-term questions to the lender, title company, or other authorized party."],["h2","During the signing"],["p","The notary signing agent presents the documents, points out factual information that the package authorizes them to identify, performs required notarial acts, and follows the orderer''s instructions. The signing agent does not negotiate terms, explain legal effect, or tell a signer whether to proceed."],["h2","Pauses and questions"],["p","If a signer has a material question, the appointment may pause while the authorized orderer is contacted. APS records neutral facts and follows documented direction; it does not create a substitute answer."],["h2","After signing"],["p","APS checks the package according to the assignment, completes required scanbacks when ordered, and returns documents using the specified method. Delivery timing depends on the orderer''s instructions and carrier acceptance."],["callout","Keep identification and financial information inside the authorized appointment workflow. Never place those details in a Resource Center form."]]'::jsonb,'[["Can the signing agent explain my interest rate?","Questions about loan terms must go to the lender, title company, or authorized orderer."],["How long will it take?","Package size, signer questions, notarial acts, and orderer instructions affect timing."],["What if I choose not to sign?","Tell the signing agent. APS will document the outcome neutrally and follow the orderer''s direction."]]'::jsonb,'[]'::jsonb,'What to Expect at a Loan Signing Appointment | Aligned Print & Scan','Prepare for the timing, identification, document handling, and neutral role of a notary signing agent at a loan signing.','published',false,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/business-document-preparation.webp' where c.name='Loan Signing' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'What Are Scanbacks in a Loan Signing?','what-are-scanbacks-loan-signing','Learn why an ordering party may require a scanned review copy before the original loan package is returned.','[["h2","A review copy before return"],["p","Scanbacks are digital images of a completed physical signing package sent through the orderer''s approved channel for review. They do not replace the original documents unless the orderer explicitly says so."],["h2","Why scanbacks are requested"],["ul",["To check signatures, initials, dates, and required notarizations before shipment.","To identify a missed item while correction may still be possible.","To meet funding, closing, or quality-control timelines.","To create an authorized operational review copy."]],["h2","What happens next"],["p","APS follows the assignment instructions, uploads only through the designated secure channel, waits for required release direction when applicable, and returns originals using the authorized label or delivery method."],["callout","Scanbacks can contain highly sensitive information. APS does not send them through article feedback, ordinary public forms, or unapproved email channels."]]'::jsonb,'[["Are scanbacks always required?","No. The ordering party determines whether they are required."],["Do scanbacks replace originals?","Usually not. Follow the orderer''s return instructions."],["Can a signer receive the scanbacks?","Document access is controlled by the transaction and ordering party; APS does not independently distribute the package."]]'::jsonb,'[]'::jsonb,'What Are Scanbacks in a Loan Signing? | Aligned Print & Scan','Learn why an ordering party may require a scanned review copy before the original loan package is returned.','published',false,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/print-scan-document-services.webp' where c.name='Loan Signing' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'How APS Business Accounts Work','how-aps-business-accounts-work','An overview of organization access, approved users, service requests, locations, billing visibility, and administrative controls.','[["h2","One organization, controlled access"],["p","An approved APS business account links authorized organization members to the same organization record. Roles determine who may create requests, review activity, view billing, or administer other members."],["h2","Services and locations"],["p","APS records the organization''s approved services and saved locations. A member selects from the options available to that account; APS still reviews each request for scope, availability, price, and eligibility."],["h2","Billing visibility"],["p","Authorized members can view organization-linked requests and permitted financial information. Payment terms are selected and changed only through APS review. A portal label is not a promise of credit approval or service acceptance."],["h2","Security basics"],["ul",["Each person uses their own invited account.","Do not share passwords or verification links.","Organization administrators should remove access promptly when a user leaves.","Sensitive documents belong only in approved request upload channels."]],["callout","Business accounts are operational access tools. They do not change notarial law, signer identity requirements, or APS''s review of an individual request."]]'::jsonb,'[["Can any employee join?","An authorized organization administrator or APS staff member must invite and approve access."],["Can members see every APS customer?","No. Business access is limited to the member''s authorized organization data."],["Does an account guarantee Net terms?","No. APS approves payment terms separately."]]'::jsonb,'[]'::jsonb,'How APS Business Accounts Work | Aligned Print & Scan','An overview of organization access, approved users, service requests, locations, billing visibility, and administrative controls.','published',false,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/business-document-preparation.webp' where c.name='Business Accounts' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'Prepaid, Due on Receipt, Net 15, and Net 30','business-payment-terms-prepaid-due-net','Understand APS business payment-term labels, when payment is due, and why an account may be placed on credit hold.','[["h2","Prepaid"],["p","Payment is required before the applicable service or fulfillment stage proceeds. The quote or invoice identifies the amount and authorized payment method."],["h2","Due on receipt"],["p","The invoice is due when issued. This is not an open-ended credit period."],["h2","Net 15 and Net 30"],["p","When APS has expressly approved Net terms, payment is due 15 or 30 calendar days from the invoice date, subject to the account agreement and invoice. Requested terms are not effective until APS approves them."],["h2","Credit holds"],["p","APS may place an organization on credit hold for overdue balances, unresolved account issues, risk review, or other documented business reasons. A hold may require payment or review before new work proceeds."],["callout","The organization portal reflects APS''s recorded terms, but the issued invoice and applicable agreement control the specific obligation. Contact APS about discrepancies before the due date."]]'::jsonb,'[["Can I select Net 30 during signup?","You may request it, but APS decides whether to approve it."],["Do weekends extend the term?","Terms are measured as stated on the invoice or agreement; do not assume an extension."],["How is a credit hold removed?","APS reviews the reason, account status, and any required payment or documentation."]]'::jsonb,'[]'::jsonb,'Prepaid, Due on Receipt, Net 15, and Net 30 | Aligned Print & Scan','Understand APS business payment-term labels, when payment is due, and why an account may be placed on credit hold.','published',false,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/aligned-brand-folder.webp' where c.name='Business Accounts' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
insert into public.resource_articles(category_id,featured_asset_id,title,slug,dek,body_blocks,faq_items,source_links,seo_title,seo_description,status,is_featured,published_at) select c.id,x.id,'How to Reset Your Business Portal Password','reset-business-portal-password','Reset access securely without sharing a password with APS or exposing a recovery link.','[["h2","Use the official recovery page"],["ol",["Open the APS Business Portal sign-in page.","Choose the password-recovery option and enter your invited email address.","If the address is eligible, use the time-limited link in the recovery email.","Create a strong, unique password and return to the portal.","Close other shared-device sessions if the device is not yours."]],["h2","A privacy-safe response"],["p","The recovery form does not confirm whether an email address exists in the system. This helps prevent account discovery. Check spam or filtered folders, allow a few minutes, and submit a new request only when needed."],["h2","APS never needs your password"],["p","APS staff cannot see your password and should never ask you to send it. Do not forward a recovery link, one-time code, or session details."],["callout","If you no longer control the invited email address, contact APS support for an identity and organization-access review. Do not create a second account to bypass access controls."]]'::jsonb,'[["Why did the form not confirm my account?","The neutral message protects account privacy."],["Can APS set a password for me?","No. You establish your own credentials through the secure recovery flow."],["What if the link expired?","Return to the official recovery page and request a new link."]]'::jsonb,'[]'::jsonb,'How to Reset Your Business Portal Password | Aligned Print & Scan','Reset access securely without sharing a password with APS or exposing a recovery link.','published',false,now() from public.resource_categories c join public.resource_assets x on x.storage_path='assets/images/resources/secure-digital-workspace.webp' where c.name='Business Accounts' on conflict(slug) do update set title=excluded.title,dek=excluded.dek,body_blocks=excluded.body_blocks,faq_items=excluded.faq_items,source_links=excluded.source_links,seo_title=excluded.seo_title,seo_description=excluded.seo_description,featured_asset_id=excluded.featured_asset_id,status='published',updated_at=now();
